<script setup>
import { onMounted, reactive, ref, computed } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { Upload, CalendarDays, MapPin, CircleAlert, CheckCircle, Eye } from 'lucide-vue-next'
import OwnerTabs from '../components/OwnerTabs.vue'
import MapView from '../components/MapView.vue'
import { ensureInstructor } from '../lib/instructor'
import { authRequest, state, notify } from '../lib/state'
const router=useRouter(),route=useRoute(),busy=ref(false),photoError=ref(''),loading=ref(true)
// Fecha de hoy en Lima y suma de días (para fechas mínimas y duplicados).
const today=new Date(Date.now()-5*3600e3).toISOString().slice(0,10)
const plusDays=(date,n)=>{const d=new Date(`${date}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
const editing=computed(()=>!!route.params.id),geoBusy=ref(false),imageUrl=ref(''),pasted=ref('')
const form=reactive({title:'',summary:'',description:'',category:'Arte',price:45,district:'Miraflores',venue:'',address:'',date:plusDays(today,14),startsAt:'16:00',endsAt:'18:00',capacity:8,level:'Principiante',materialsIncluded:'',materialsBring:'',image:'/images/ceramica.jpg',lat:null,lon:null,enrollmentOpen:true,recurrence:'once',repeatCount:4})
const fields=['title','summary','description','category','price','district','venue','address','date','startsAt','endsAt','capacity','level','materialsIncluded','materialsBring','image','lat','lon']
const progress=computed(()=>fields.filter(k=>String(form[k]??'').trim()).length)
const picked=computed(()=>Number.isFinite(form.lat)&&Number.isFinite(form.lon)?[form.lat,form.lon]:null)
// Mismo punto-en-polígono que valida el backend (backend/src/data.js → insideArea).
const inside=(d,[lat,lon])=>{const poly=state.meta.districtAreas?.[d];if(!poly)return false;let ok=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const [yi,xi]=poly[i],[yj,xj]=poly[j];if((yi>lat)!==(yj>lat)&&lon<((xj-xi)*(lat-yi))/(yj-yi)+xi)ok=!ok}return ok}
const mapCenter=computed(()=>picked.value||state.meta.districtCenters[form.district]||[-12.13,-77.025])
const locationError=computed(()=>picked.value&&!inside(form.district,picked.value)?`El punto marcado está fuera de ${form.district}. Muévelo o cambia el distrito.`:'')
function pick([lat,lon]){form.lat=lat;form.lon=lon;const d=state.meta.districts.find(x=>inside(x,[lat,lon]));if(d&&!inside(form.district,[lat,lon])){form.district=d;notify(`Distrito actualizado a ${d} según el mapa.`)}}
// Geocodificación gratuita con Nominatim (OpenStreetMap). Se limita a Miraflores y Barranco.
async function geocode(){if(!form.address.trim())return notify('Escribe primero la dirección.');try{geoBusy.value=true;const q=encodeURIComponent(`${form.address}, ${form.district}, Lima, Perú`);const r=await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=pe&q=${q}`,{headers:{'Accept-Language':'es'}});const [hit]=await r.json();if(!hit)return notify('No encontramos la dirección; marca el punto directamente en el mapa.');pick([Number(Number(hit.lat).toFixed(6)),Number(Number(hit.lon).toFixed(6))]);notify('Ubicación encontrada. Verifica el pin en el mapa.')}catch{notify('No se pudo buscar la dirección. Marca el punto en el mapa.')}finally{geoBusy.value=false}}
// Idea de la rama de Santiago: copiar las coordenadas del local desde Google Maps
// (clic derecho sobre el punto → se copian como "-12.1211, -77.0297") y pegarlas aquí.
function pasteCoords(){const m=pasted.value.match(/(-?\d{1,2}\.\d+)\s*,\s*(-?\d{1,3}\.\d+)/);if(!m)return notify('Pega dos números separados por coma, por ejemplo -12.1211, -77.0297');pick([Number(Number(m[1]).toFixed(6)),Number(Number(m[2]).toFixed(6))]);pasted.value=''}
function useImageUrl(){const u=imageUrl.value.trim();if(!/^https:\/\/\S+$/i.test(u)){photoError.value='El enlace de la imagen debe empezar con https://';return}photoError.value='';form.image=u}
async function load(){try{await ensureInstructor();const source=String(route.params.id||route.query.duplicate||'');if(source){const w=(await authRequest('/instructor/workshops')).items.find(w=>w.id===source);if(w){for(const k of fields)form[k]=w[k];form.enrollmentOpen=w.enrollmentOpen!==false;if(!editing.value){form.title+= ' — nueva fecha';form.date=plusDays(w.date>today?w.date:today,7)}}else{notify('No se encontró el taller solicitado.')}}}catch(e){notify(e.message)}finally{loading.value=false}}
onMounted(load)
function uploadPhoto(event){const file=event.target.files?.[0];if(!file)return;photoError.value='';if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1_100_000){photoError.value='Usa JPG, PNG o WebP de hasta 1 MB.';return}const reader=new FileReader();reader.onload=()=>{form.image=String(reader.result)};reader.onerror=()=>{photoError.value='No fue posible leer la foto.'};reader.readAsDataURL(file)}
async function publish(){try{busy.value=true;const path=editing.value?`/instructor/workshops/${route.params.id}`:'/instructor/workshops';await authRequest(path,{method:editing.value?'PUT':'POST',body:form});notify(editing.value?'Taller actualizado correctamente':'¡Tu taller ya está publicado!');router.push('/tallerista/talleres')}catch(e){notify(e.message)}finally{busy.value=false}}
</script>
<template><div class="page owner-page"><div class="page-heading"><div><div class="eyebrow earth">PUBLICACIÓN ESTRUCTURADA</div><h1>{{editing?'Editar taller':'Crear nuevo taller'}}</h1><p class="muted">Completa los campos obligatorios para que los clientes comparen tu oferta con información clara.</p></div><div class="progress-pill"><CheckCircle :size="16"/> {{progress}}/{{fields.length}} campos completos</div></div><OwnerTabs/>
<div v-if="loading" class="loading-area">Preparando formulario...</div><form v-else class="editor-form" @submit.prevent="publish"><div class="editor-main"><section class="form-card"><h2>1. Identidad del taller</h2><div class="form-grid"><label class="span-all">Título del taller <span class="required">*</span><input v-model="form.title" required minlength="5" maxlength="90" placeholder="Ej. Linograbado para principiantes"/></label><label>Categoría <span class="required">*</span><select v-model="form.category" required><option v-for="c in state.meta.categories" :key="c">{{c}}</option></select></label><label>Nivel de conocimiento <span class="required">*</span><select v-model="form.level" required><option>Principiante</option><option>Intermedio</option><option>Avanzado</option><option>Todos los niveles</option></select></label><label class="span-all">Resumen corto <span class="required">*</span><input v-model="form.summary" minlength="8" maxlength="180" required placeholder="Qué aprenderá el participante en una frase"/></label><label class="span-all">Descripción del taller <span class="required">*</span><textarea v-model="form.description" required minlength="20" rows="4" placeholder="Describe contenido, objetivos y experiencia esperada..."/></label></div></section>
<section class="form-card"><h2>2. Ubicación, horarios y cupos</h2><div class="form-grid"><label>Precio en soles <span class="required">*</span><input v-model.number="form.price" required type="number" min="0" max="9999"/></label><label>Cupos totales <span class="required">*</span><input v-model.number="form.capacity" required type="number" min="1" max="1000"/></label><label>Distrito <span class="required">*</span><select v-model="form.district" required><option v-for="d in state.meta.districts" :key="d">{{d}}</option></select></label><label>Nombre del local <span class="required">*</span><input v-model="form.venue" required placeholder="Ej. Taller Creativo Barranco"/></label><label class="span-all">Dirección o referencia <span class="required">*</span><span class="addr-row"><input v-model="form.address" required placeholder="Calle y número, p. ej. Av. Grau 320"/><button type="button" class="btn light sm" :disabled="geoBusy" @click="geocode"><MapPin :size="15"/> {{geoBusy?'Buscando...':'Ubicar en el mapa'}}</button></span></label>
<div class="span-all"><b>Ubicación exacta en el mapa <span class="required">*</span></b><p class="small muted">Toca el mapa para colocar el pin del local. Se usa en "Cerca de mí" y en la ficha del taller.</p><MapView :markers="[]" :areas="state.meta.districtAreas" :picked="picked" :center="mapCenter" :zoom="15" :pickable="true" :fit="false" height="300px" @pick="pick"/><div class="addr-row" style="margin-top:8px"><input v-model="pasted" placeholder="O pega coordenadas de Google Maps: -12.1211, -77.0297" aria-label="Pegar coordenadas" @keydown.enter.prevent="pasteCoords"/><button type="button" class="btn outline sm" @click="pasteCoords">Usar coordenadas</button></div><p v-if="picked" class="small muted">Coordenadas: {{form.lat}}, {{form.lon}}</p><p v-if="locationError" class="error-text">{{locationError}}</p></div><label>Fecha de la sesión <span class="required">*</span><input v-model="form.date" required type="date" :min="today"/></label><label>Hora de inicio <span class="required">*</span><input v-model="form.startsAt" required type="time"/></label><label>Hora de fin <span class="required">*</span><input v-model="form.endsAt" required type="time"/></label><label v-if="!editing">Tipo de taller<select v-model="form.recurrence"><option value="once">Fecha única</option><option value="weekly">Recurrente semanal</option></select></label><label v-if="!editing && form.recurrence==='weekly'">Sesiones semanales<input v-model.number="form.repeatCount" type="number" min="2" max="8" required/></label><label class="span-all check-line"><input v-model="form.enrollmentOpen" type="checkbox"/> Inscripciones abiertas (desmarca para cerrar cupos temporalmente sin ocultar el taller)</label><p class="muted small span-all" v-if="!editing && form.recurrence==='weekly'">Cada fecha se publica como una sesión con cupos independientes. Podrás editarla desde Mis talleres.</p></div></section>
<section class="form-card"><h2>3. Materiales necesarios</h2><div class="form-grid"><label class="span-all">Materiales incluidos en el precio <span class="required">*</span><textarea v-model="form.materialsIncluded" required rows="3" placeholder="Ej. Arcilla, pintura, herramientas..."/></label><label class="span-all">¿Qué debe traer el participante? <span class="required">*</span><textarea v-model="form.materialsBring" required rows="3" placeholder="Ej. Mandil, libreta; escribe Ninguno si no necesita nada"/></label></div></section></div>
<aside class="editor-side"><section class="form-card sticky"><h2>4. Foto principal <span class="required">*</span></h2><p class="small muted">Usa una foto incluida en la galería o adjunta una imagen de hasta 1 MB.</p><img class="photo-preview" :src="form.image" alt="Vista previa de publicación"/><div class="photo-choices"><button v-for="img in state.meta.images" type="button" :key="img" :class="{selected:form.image===img}" @click="form.image=img"><img :src="img" :alt="`Fotografía de ejemplo ${img}`"/></button></div><div class="url-row"><input v-model="imageUrl" type="url" placeholder="https://… enlace a una foto tuya" aria-label="Enlace de imagen"/><button type="button" class="btn outline sm" @click="useImageUrl">Usar enlace</button></div><label class="file-upload"><Upload :size="17"/> Cargar foto propia<input type="file" accept="image/png,image/jpeg,image/webp" @change="uploadPhoto"/></label><div v-if="photoError" class="error-text">{{photoError}}</div><div class="form-help"><CircleAlert :size="17"/> No se puede publicar mientras falte un campo obligatorio. Se valida también en el backend.</div><button type="submit" class="btn primary full" :disabled="busy||progress<fields.length||!!locationError">{{busy?'Guardando...':editing?'Guardar cambios':'Publicar taller'}}</button><RouterLink to="/tallerista/talleres" class="btn outline full">Cancelar</RouterLink></section></aside></form></div></template>

<style scoped>.addr-row{display:flex;gap:8px}.addr-row input{flex:1}.check-line{display:flex!important;gap:8px;align-items:center}.url-row{display:flex;gap:6px;margin:10px 0}.url-row input{flex:1;min-width:0;padding:9px;border:1px solid #dfcbb5;border-radius:10px}</style>
